H.background();
const baseA = P.A;
let Adeg = baseA + 12 * Math.sin(t * 0.6);
Adeg = Math.max(20, Math.min(Adeg, 120));
let Bdeg = 50;
let Cdeg = 180 - Adeg - Bdeg;
if (Cdeg < 15) { Cdeg = 15; Bdeg = 180 - Adeg - Cdeg; }
const A = Adeg * Math.PI / 180, B = Bdeg * Math.PI / 180, C = Cdeg * Math.PI / 180;
const ax = 180, ay = 420, c = 360;
const bx = ax + c, by = ay;
const k = c / Math.sin(C);
const aLen = k * Math.sin(A);
const bLen = k * Math.sin(B);
const Cx = ax + bLen * Math.cos(A);
const Cy = ay - bLen * Math.sin(A);
H.text("Law of sines:  a/sinA = b/sinB = c/sinC", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Each side over the sine of its opposite angle gives the SAME ratio (the circumdiameter).", 24, 52, { color: H.colors.sub, size: 13 });
H.path([[ax, ay], [bx, by], [Cx, Cy]], { color: H.colors.ink, width: 3, fill: "rgba(110,168,254,0.10)", close: true });
H.line(ax, ay, bx, by, { color: H.colors.accent, width: 4 });
H.line(bx, by, Cx, Cy, { color: H.colors.good, width: 4 });
H.line(ax, ay, Cx, Cy, { color: H.colors.violet, width: 4 });
H.text("A", ax - 18, ay + 6, { color: H.colors.yellow, size: 15, weight: 700 });
H.text("B", bx + 8, by + 6, { color: H.colors.yellow, size: 15, weight: 700 });
H.text("C", Cx, Cy - 14, { color: H.colors.yellow, size: 15, weight: 700, align: "center" });
H.text("c", (ax + bx) / 2, ay + 22, { color: H.colors.accent, size: 13, align: "center" });
H.text("a", (bx + Cx) / 2 + 10, (by + Cy) / 2, { color: H.colors.good, size: 13 });
H.text("b", (ax + Cx) / 2 - 18, (ay + Cy) / 2, { color: H.colors.violet, size: 13 });
const ra = aLen / Math.sin(A), rb = bLen / Math.sin(B), rc = c / Math.sin(C);
H.rect(560, 80, 320, 132, { fill: H.colors.panel, stroke: H.colors.grid, width: 1, radius: 8 });
H.text("a/sinA = " + ra.toFixed(1), 578, 112, { color: H.colors.good, size: 14 });
H.text("b/sinB = " + rb.toFixed(1), 578, 140, { color: H.colors.violet, size: 14 });
H.text("c/sinC = " + rc.toFixed(1), 578, 168, { color: H.colors.accent, size: 14 });
H.text("all equal -> " + rc.toFixed(1) + " px", 578, 196, { color: H.colors.sub, size: 13, weight: 700 });
H.text("A=" + Adeg.toFixed(0) + "  B=" + Bdeg.toFixed(0) + "  C=" + Cdeg.toFixed(0), 24, 76, { color: H.colors.sub, size: 13 });
